mapper.insert:
insert into cms_content_type (site_id, code, name, kind, hierarchical, detail_url_pattern, list_url_pattern, per_page, status, sort) select #{siteId}, v.code, v.name, v.kind, v.hierarchical, v.detail_url_pattern, v.list_url_pattern, v.per_page, 1, v.sort from (values
(#{t.code,jdbcType=VARCHAR}::varchar, #{t.name,jdbcType=VARCHAR}::varchar, #{t.kind,jdbcType=VARCHAR}::varchar, #{t.hierarchical,jdbcType=SMALLINT}::smallint, #{t.detailUrlPattern,jdbcType=VARCHAR}::varchar, #{t.listUrlPattern,jdbcType=VARCHAR}::varchar, #{t.perPage,jdbcType=INTEGER}::int, #{t.sort,jdbcType=INTEGER}::int)
) as v(code, name, kind, hierarchical, detail_url_pattern, list_url_pattern, per_page, sort) where not exists (select 1 from cms_content_type x where x.site_id = #{siteId} and x.code = v.code and x.deleted = 0)
